import * as THREE from 'three';

/**
 * ProceduralTextures.js
 * Module 1: High-Resolution AI PBR Diffuse Textures & High-Frequency Geometric Bump Maps
 * for all Visceral Organs (Hollow Organs, Solid Organs & Peritoneum) — ĐHYHN Standard.
 *
 * Integrates:
 * - Authentic 2D PBR Diffuse Maps generated by AI (Nano Banana / Imagen) from ./assets/textures/
 * - Procedural High-Frequency Grayscale Bump/Height Maps for tangible 3D lighting relief
 */
export class ProceduralTextures {
  constructor() {
    this._cache = null;
    this._loader = new THREE.TextureLoader();
  }

  /**
   * Returns cached textures or loads/generates them on first request.
   */
  getTextures() {
    if (this._cache) {
      return this._cache;
    }
    this._cache = this._buildAllTextures();
    return this._cache;
  }

  /**
   * Pre-warms the texture cache during browser idle time so initial page load is instant.
   */
  warmupAsync(onReady) {
    if (this._cache) {
      if (onReady) onReady(this._cache);
      return;
    }
    const schedule = window.requestIdleCallback || ((cb) => setTimeout(cb, 60));
    schedule(() => {
      const tex = this.getTextures();
      if (onReady) onReady(tex);
    });
  }

  /**
   * Helper to load an image texture from disk with repeat wrapping.
   */
  _loadTexture(path, repeatX = 2, repeatY = 2) {
    const tex = this._loader.load(path);
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(repeatX, repeatY);
    return tex;
  }

  _buildAllTextures() {
    const createCanvas = (size = 256) => {
      const canvas = document.createElement('canvas');
      canvas.width = size;
      canvas.height = size;
      return canvas;
    };

    const result = {};

    // =========================================================================
    // 1. DẠ DÀY (STOMACH / GASTER — 6 HISTOLOGICAL LAYERS)
    // =========================================================================
    result.serosaTexture = this._loadTexture('./assets/textures/serosa_diffuse.png', 2, 2);

    result.longitudinalMuscleTexture = this._loadTexture('./assets/textures/longitudinal_muscle_diffuse.png', 2, 3);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      bCtx.lineWidth = 2.0;
      for (let x = 0; x < 256; x += 4) {
        bCtx.strokeStyle = (x % 8 === 0) ? '#e2e8f0' : '#1e293b';
        bCtx.beginPath();
        bCtx.moveTo(x, 0);
        bCtx.lineTo(x, 256);
        bCtx.stroke();
      }
      result.longitudinalMuscleBump = new THREE.CanvasTexture(bCanvas);
      result.longitudinalMuscleBump.wrapS = THREE.RepeatWrapping;
      result.longitudinalMuscleBump.wrapT = THREE.RepeatWrapping;
      result.longitudinalMuscleBump.repeat.set(2, 3);
    }

    result.circularMuscleTexture = this._loadTexture('./assets/textures/circular_muscle_diffuse.png', 3, 2);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      bCtx.lineWidth = 2.2;
      for (let y = 0; y < 256; y += 4) {
        bCtx.strokeStyle = (y % 8 === 0) ? '#f1f5f9' : '#0f172a';
        bCtx.beginPath();
        bCtx.moveTo(0, y);
        bCtx.lineTo(256, y);
        bCtx.stroke();
      }
      result.circularMuscleBump = new THREE.CanvasTexture(bCanvas);
      result.circularMuscleBump.wrapS = THREE.RepeatWrapping;
      result.circularMuscleBump.wrapT = THREE.RepeatWrapping;
      result.circularMuscleBump.repeat.set(3, 2);
    }

    result.obliqueMuscleTexture = this._loadTexture('./assets/textures/stomach_oblique_diffuse.png', 2, 2);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      bCtx.lineWidth = 2.0;
      for (let i = -256; i < 256; i += 5) {
        bCtx.strokeStyle = (i % 10 === 0) ? '#f8fafc' : '#18181b';
        bCtx.beginPath();
        bCtx.moveTo(i, 0);
        bCtx.lineTo(i + 256, 256);
        bCtx.stroke();
      }
      result.obliqueMuscleBump = new THREE.CanvasTexture(bCanvas);
      result.obliqueMuscleBump.wrapS = THREE.RepeatWrapping;
      result.obliqueMuscleBump.wrapT = THREE.RepeatWrapping;
      result.obliqueMuscleBump.repeat.set(2, 2);
    }

    result.submucosaTexture = this._loadTexture('./assets/textures/submucosa_diffuse.png', 2, 2);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      bCtx.strokeStyle = '#a0a0a0';
      bCtx.lineWidth = 1.5;
      for (let i = 0; i < 30; i++) {
        bCtx.beginPath();
        let x = Math.random() * 256, y = Math.random() * 256;
        bCtx.moveTo(x, y);
        for (let s = 0; s < 3; s++) {
          x += (Math.random() - 0.5) * 40;
          y += (Math.random() - 0.5) * 40;
          bCtx.lineTo(x, y);
        }
        bCtx.stroke();
      }
      result.submucosaBump = new THREE.CanvasTexture(bCanvas);
      result.submucosaBump.wrapS = THREE.RepeatWrapping;
      result.submucosaBump.wrapT = THREE.RepeatWrapping;
      result.submucosaBump.repeat.set(2, 2);
    }

    result.mucosaTexture = this._loadTexture('./assets/textures/mucosa_diffuse.png', 2, 2);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      for (let y = 12; y < 256; y += 20) {
        bCtx.strokeStyle = '#101010';
        bCtx.lineWidth = 9;
        bCtx.beginPath();
        bCtx.moveTo(0, y + 4);
        for (let x = 0; x <= 256; x += 14) {
          bCtx.lineTo(x, y + 4 + Math.sin((x / 256) * Math.PI * 4 + (y / 18)) * 8);
        }
        bCtx.stroke();

        bCtx.strokeStyle = '#ffffff';
        bCtx.lineWidth = 4;
        bCtx.beginPath();
        bCtx.moveTo(0, y - 1);
        for (let x = 0; x <= 256; x += 14) {
          bCtx.lineTo(x, y - 1 + Math.sin((x / 256) * Math.PI * 4 + (y / 18)) * 8);
        }
        bCtx.stroke();
      }
      result.mucosaBump = new THREE.CanvasTexture(bCanvas);
      result.mucosaBump.wrapS = THREE.RepeatWrapping;
      result.mucosaBump.wrapT = THREE.RepeatWrapping;
      result.mucosaBump.repeat.set(2, 2);
    }

    // =========================================================================
    // 2. TÁ TRÀNG (DUODENUM — 5 HISTOLOGICAL LAYERS)
    // =========================================================================
    result.duodenumSerosaTexture = this._loadTexture('./assets/textures/serosa_diffuse.png', 2, 2);

    result.duodenumLongitudinalMuscleTexture = this._loadTexture('./assets/textures/longitudinal_muscle_diffuse.png', 2, 3);
    result.duodenumLongitudinalMuscleBump = result.longitudinalMuscleBump;

    result.duodenumCircularMuscleTexture = this._loadTexture('./assets/textures/circular_muscle_diffuse.png', 3, 2);
    result.duodenumCircularMuscleBump = result.circularMuscleBump;

    // Duodenum Submucosa with Brunner's Glands
    result.duodenumSubmucosaTexture = this._loadTexture('./assets/textures/duodenum_brunner_diffuse.png', 2, 2);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      for (let i = 0; i < 220; i++) {
        const gx = Math.random() * 256;
        const gy = Math.random() * 256;
        const gr = Math.random() * 3 + 1.5;
        const rad = bCtx.createRadialGradient(gx, gy, 0, gx, gy, gr);
        rad.addColorStop(0, '#ffffff');
        rad.addColorStop(1, '#808080');
        bCtx.fillStyle = rad;
        bCtx.beginPath();
        bCtx.arc(gx, gy, gr, 0, Math.PI * 2);
        bCtx.fill();
      }
      result.duodenumSubmucosaBump = new THREE.CanvasTexture(bCanvas);
      result.duodenumSubmucosaBump.wrapS = THREE.RepeatWrapping;
      result.duodenumSubmucosaBump.wrapT = THREE.RepeatWrapping;
      result.duodenumSubmucosaBump.repeat.set(2, 2);
    }

    // Duodenum Mucosa with Kerckring Folds
    result.duodenumMucosaTexture = this._loadTexture('./assets/textures/duodenum_kerckring_diffuse.png', 2, 3);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      for (let y = 8; y < 256; y += 16) {
        bCtx.strokeStyle = '#ffffff';
        bCtx.lineWidth = 5;
        bCtx.beginPath();
        bCtx.moveTo(0, y);
        for (let x = 0; x <= 256; x += 16) {
          bCtx.lineTo(x, y + Math.sin((x / 256) * Math.PI * 6) * 3);
        }
        bCtx.stroke();

        bCtx.strokeStyle = '#101010';
        bCtx.lineWidth = 5;
        bCtx.beginPath();
        bCtx.moveTo(0, y + 6);
        for (let x = 0; x <= 256; x += 16) {
          bCtx.lineTo(x, y + 6 + Math.sin((x / 256) * Math.PI * 6) * 3);
        }
        bCtx.stroke();
      }
      result.duodenumMucosaBump = new THREE.CanvasTexture(bCanvas);
      result.duodenumMucosaBump.wrapS = THREE.RepeatWrapping;
      result.duodenumMucosaBump.wrapT = THREE.RepeatWrapping;
      result.duodenumMucosaBump.repeat.set(2, 3);
    }

    // =========================================================================
    // 3. RUỘT NON (SMALL INTESTINE — 5 HISTOLOGICAL LAYERS)
    // =========================================================================
    result.siSerosaTexture = this._loadTexture('./assets/textures/serosa_diffuse.png', 2, 2);

    result.siLongitudinalMuscleTexture = this._loadTexture('./assets/textures/longitudinal_muscle_diffuse.png', 2, 3);
    result.siLongitudinalMuscleBump = result.longitudinalMuscleBump;

    result.siCircularMuscleTexture = this._loadTexture('./assets/textures/circular_muscle_diffuse.png', 3, 2);
    result.siCircularMuscleBump = result.circularMuscleBump;

    result.siSubmucosaTexture = this._loadTexture('./assets/textures/submucosa_diffuse.png', 2, 2);
    result.siSubmucosaBump = result.submucosaBump;

    // Small Intestine Mucosa with Villi
    result.siMucosaTexture = this._loadTexture('./assets/textures/small_intestine_villi_diffuse.png', 3, 3);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      for (let i = 0; i < 400; i++) {
        const vx = Math.random() * 256, vy = Math.random() * 256;
        bCtx.fillStyle = Math.random() > 0.5 ? '#ffffff' : '#202020';
        bCtx.beginPath();
        bCtx.arc(vx, vy, 1.8, 0, Math.PI * 2);
        bCtx.fill();
      }
      result.siMucosaBump = new THREE.CanvasTexture(bCanvas);
      result.siMucosaBump.wrapS = THREE.RepeatWrapping;
      result.siMucosaBump.wrapT = THREE.RepeatWrapping;
      result.siMucosaBump.repeat.set(3, 3);
    }

    // =========================================================================
    // 4. ĐẠI TRÀNG / RUỘT GIÀ (COLON — 5 HISTOLOGICAL LAYERS)
    // =========================================================================
    // Colon Serosa (smooth glistening peritoneum)
    result.colonSerosaTexture = this._loadTexture('./assets/textures/serosa_diffuse.png', 2, 2);
    // Dedicated Epiploic Appendages (Bọng mỡ mạc nối)
    result.colonEpiploicTexture = this._loadTexture('./assets/textures/colon_epiploic_diffuse.png', 2, 6);

    // Colon Longitudinal Muscle with Taeniae Coli
    result.colonLongitudinalMuscleTexture = this._loadTexture('./assets/textures/colon_taeniae_diffuse.png', 1, 2);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      for (const tx of [64, 128, 192]) {
        const rGrad = bCtx.createLinearGradient(tx - 15, 0, tx + 15, 0);
        rGrad.addColorStop(0, '#808080');
        rGrad.addColorStop(0.5, '#ffffff');
        rGrad.addColorStop(1, '#808080');
        bCtx.fillStyle = rGrad;
        bCtx.fillRect(tx - 15, 0, 30, 256);
      }
      result.colonLongitudinalMuscleBump = new THREE.CanvasTexture(bCanvas);
      result.colonLongitudinalMuscleBump.wrapS = THREE.RepeatWrapping;
      result.colonLongitudinalMuscleBump.wrapT = THREE.RepeatWrapping;
      result.colonLongitudinalMuscleBump.repeat.set(1, 2);
    }

    result.colonCircularMuscleTexture = this._loadTexture('./assets/textures/circular_muscle_diffuse.png', 3, 2);
    result.colonCircularMuscleBump = result.circularMuscleBump;

    result.colonSubmucosaTexture = this._loadTexture('./assets/textures/submucosa_diffuse.png', 2, 2);
    result.colonSubmucosaBump = result.submucosaBump;

    // Colon Mucosa with Plicae Semilunares
    result.colonMucosaTexture = this._loadTexture('./assets/textures/colon_semilunar_diffuse.png', 2, 2);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#808080';
      bCtx.fillRect(0, 0, 256, 256);
      for (let y = 15; y < 256; y += 32) {
        bCtx.strokeStyle = '#ffffff';
        bCtx.lineWidth = 8;
        bCtx.beginPath();
        bCtx.moveTo(0, y);
        for (let x = 0; x <= 256; x += 16) {
          bCtx.lineTo(x, y + Math.sin((x / 256) * Math.PI * 4) * 7);
        }
        bCtx.stroke();

        bCtx.strokeStyle = '#101010';
        bCtx.lineWidth = 8;
        bCtx.beginPath();
        bCtx.moveTo(0, y + 8);
        for (let x = 0; x <= 256; x += 16) {
          bCtx.lineTo(x, y + 8 + Math.sin((x / 256) * Math.PI * 4) * 7);
        }
        bCtx.stroke();
      }
      result.colonMucosaBump = new THREE.CanvasTexture(bCanvas);
      result.colonMucosaBump.wrapS = THREE.RepeatWrapping;
      result.colonMucosaBump.wrapT = THREE.RepeatWrapping;
      result.colonMucosaBump.repeat.set(2, 2);
    }

    // =========================================================================
    // 5. TÚI MẬT (GALLBLADDER — 4 HISTOLOGICAL LAYERS)
    // =========================================================================
    result.gbSerosaTexture = this._loadTexture('./assets/textures/serosa_diffuse.png', 2, 2);

    // Gallbladder Crisscross Muscle
    result.gbMuscleTexture = this._loadTexture('./assets/textures/gallbladder_muscle_diffuse.png', 2, 2);
    result.gbMuscleBump = result.obliqueMuscleBump;

    result.gbSubmucosaTexture = this._loadTexture('./assets/textures/submucosa_diffuse.png', 2, 2);
    result.gbSubmucosaBump = result.submucosaBump;

    // Gallbladder Honeycomb Mucosa
    result.gbMucosaTexture = this._loadTexture('./assets/textures/gallbladder_honeycomb_diffuse.png', 3, 3);
    {
      const bCanvas = createCanvas(256);
      const bCtx = bCanvas.getContext('2d');
      bCtx.fillStyle = '#202020';
      bCtx.fillRect(0, 0, 256, 256);
      const hexR = 20;
      bCtx.strokeStyle = '#ffffff';
      bCtx.lineWidth = 3.5;
      for (let row = 0; row < 16; row++) {
        for (let col = 0; col < 16; col++) {
          const cx = col * hexR * 1.65 + (row % 2) * hexR * 0.82;
          const cy = row * hexR * 1.45;
          bCtx.beginPath();
          for (let k = 0; k < 6; k++) {
            const ang = (k * Math.PI) / 3;
            const vx = cx + Math.cos(ang) * hexR * 0.85;
            const vy = cy + Math.sin(ang) * hexR * 0.85;
            if (k === 0) bCtx.moveTo(vx, vy);
            else bCtx.lineTo(vx, vy);
          }
          bCtx.closePath();
          bCtx.stroke();
        }
      }
      result.gbMucosaBump = new THREE.CanvasTexture(bCanvas);
      result.gbMucosaBump.wrapS = THREE.RepeatWrapping;
      result.gbMucosaBump.wrapT = THREE.RepeatWrapping;
      result.gbMucosaBump.repeat.set(3, 3);
    }

    // =========================================================================
    // 6. THỰC QUẢN (ESOPHAGUS — 5 HISTOLOGICAL LAYERS)
    // =========================================================================
    // Esophagus Loose Fibrous Adventitia
    result.esoAdventitiaTexture = this._loadTexture('./assets/textures/esophagus_adventitia_diffuse.png', 2, 2);

    result.esoLongitudinalMuscleTexture = this._loadTexture('./assets/textures/longitudinal_muscle_diffuse.png', 2, 3);
    result.esoLongitudinalMuscleBump = result.longitudinalMuscleBump;

    result.esoCircularMuscleTexture = this._loadTexture('./assets/textures/circular_muscle_diffuse.png', 3, 2);
    result.esoCircularMuscleBump = result.circularMuscleBump;

    result.esoSubmucosaTexture = this._loadTexture('./assets/textures/submucosa_diffuse.png', 2, 2);
    result.esoSubmucosaBump = result.submucosaBump;

    // Esophagus Stratified Squamous Mucosa
    result.esoMucosaTexture = this._loadTexture('./assets/textures/esophagus_squamous_diffuse.png', 2, 3);
    result.esoMucosaBump = result.longitudinalMuscleBump;

    // =========================================================================
    // 7. ỐNG DẪN MẬT (BILE DUCT — 4 HISTOLOGICAL LAYERS)
    // =========================================================================
    // Layer 1: Tunica Fibrosa / Adventitia (Vỏ mô liên kết xơ ngoài cùng)
    {
      const c = createCanvas(256);
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#6b7f5e'; // Olive-tinted fibrous adventitia
      ctx.fillRect(0, 0, 256, 256);
      ctx.strokeStyle = 'rgba(215, 230, 200, 0.45)';
      ctx.lineWidth = 1.5;
      for (let i = 0; i < 40; i++) {
        ctx.beginPath();
        let y = Math.random() * 256;
        ctx.moveTo(0, y);
        ctx.bezierCurveTo(75, y + (Math.random() - 0.5) * 25, 175, y + (Math.random() - 0.5) * 25, 256, y);
        ctx.stroke();
      }
      ctx.strokeStyle = 'rgba(180, 50, 50, 0.4)';
      ctx.lineWidth = 1.0;
      for (let i = 0; i < 15; i++) {
        ctx.beginPath();
        let sx = Math.random() * 256, sy = Math.random() * 256;
        ctx.moveTo(sx, sy);
        ctx.lineTo(sx + (Math.random() - 0.5) * 40, sy + Math.random() * 35);
        ctx.stroke();
      }
      result.bileAdventitiaTexture = new THREE.CanvasTexture(c);
      result.bileAdventitiaTexture.wrapS = THREE.RepeatWrapping;
      result.bileAdventitiaTexture.wrapT = THREE.RepeatWrapping;
      result.bileAdventitiaTexture.repeat.set(2, 3);
    }

    // Layer 2: Tunica Muscularis (Lớp cơ trơn & cơ vòng Oddi)
    result.bileMuscleTexture = this._loadTexture('./assets/textures/circular_muscle_diffuse.png', 2, 3) || result.circularMuscleTexture || result.gbMuscleTexture;
    result.bileMuscleBump = result.circularMuscleBump || result.obliqueMuscleBump;

    // Layer 3: Tela Submucosa / Lamina Propria (Lớp đệm giàu mạch & tuyến ống mật)
    result.bileSubmucosaTexture = this._loadTexture('./assets/textures/submucosa_diffuse.png', 2, 2) || result.gbSubmucosaTexture;
    result.bileSubmucosaBump = result.submucosaBump;

    // Layer 4: Tunica Mucosa (Biểu mô trụ đơn & nếp gấp dọc ngấm dịch mật vàng óng)
    {
      const c = createCanvas(256);
      const ctx = c.getContext('2d');
      const grad = ctx.createLinearGradient(0, 0, 256, 0);
      grad.addColorStop(0, '#c99833');
      grad.addColorStop(0.5, '#e0b54a');
      grad.addColorStop(1, '#b58326');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, 256, 256);

      // Fine longitudinal mucosal folds (plicae longitudinales)
      ctx.strokeStyle = 'rgba(110, 75, 15, 0.4)';
      for (let x = 0; x < 256; x += 16) {
        ctx.lineWidth = 2.0;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.bezierCurveTo(x + 4, 85, x - 4, 170, x, 256);
        ctx.stroke();
      }
      result.bileMucosaTexture = new THREE.CanvasTexture(c);
      result.bileMucosaTexture.wrapS = THREE.RepeatWrapping;
      result.bileMucosaTexture.wrapT = THREE.RepeatWrapping;
      result.bileMucosaTexture.repeat.set(2, 3);

      const bc = createCanvas(256);
      const bctx = bc.getContext('2d');
      bctx.fillStyle = '#808080';
      bctx.fillRect(0, 0, 256, 256);
      bctx.strokeStyle = '#ffffff';
      for (let x = 0; x < 256; x += 16) {
        bctx.lineWidth = 2.5;
        bctx.beginPath();
        bctx.moveTo(x, 0);
        bctx.bezierCurveTo(x + 4, 85, x - 4, 170, x, 256);
        bctx.stroke();
      }
      result.bileMucosaBump = new THREE.CanvasTexture(bc);
      result.bileMucosaBump.wrapS = THREE.RepeatWrapping;
      result.bileMucosaBump.wrapT = THREE.RepeatWrapping;
      result.bileMucosaBump.repeat.set(2, 3);
    }

    // =========================================================================
    // 8. TẠNG ĐẶC & PHÚC MẠC (SOLID ORGANS & PERITONEUM)
    // =========================================================================
    result.liverTexture = this._loadTexture('./assets/textures/liver_parenchyma_diffuse.png', 3, 3);
    result.pancreasTexture = this._loadTexture('./assets/textures/pancreas_lobular_diffuse.png', 3, 3);
    result.greaterOmentumTexture = this._loadTexture('./assets/textures/greater_omentum_diffuse.png', 2, 2);

    // =========================================================================
    // 9. VÙNG MIỆNG & HỌNG (ORAL CAVITY & PHARYNX)
    // =========================================================================
    result.tongueTexture = this._loadTexture('./assets/textures/tongue_diffuse.png', 3, 3);
    result.pharynxTexture = this._loadTexture('./assets/textures/pharynx_diffuse.png', 2, 2);
    result.gingivaTexture = this._loadTexture('./assets/textures/gingiva_diffuse.png', 3, 3);
    result.palateTexture = this._loadTexture('./assets/textures/palate_diffuse.png', 2, 2);
    result.teethTexture = this._loadTexture('./assets/textures/teeth_diffuse.png', 4, 4);
    result.salivaryGlandTexture = this._loadTexture('./assets/textures/salivary_gland_diffuse.png', 3, 3);
    result.boneTexture = this._loadTexture('./assets/textures/bone_diffuse.png', 2, 2);

    return result;
  }
}
